// Node's own resolution rule sends this require to vt2-alias-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// ===========================================================================
// THE CALLEE THE WHOLE CASE TURNS ON -- and note that there is nothing
// interesting about it. It is a local, never-reassigned function
// declaration whose body throws on every path: exactly the shape RWF-016
// has proven fatal since the beginning.
//
// What was open was never the CALLEE. It was the CALL SITE.
// ===========================================================================
function bail() {
  throw new Error("fast mode is not supported by this build");
}

function noop() {
  return "noop";
}

// The alias. By the language's own rules `alias` and `bail` are the SAME
// function object, so `alias()` enters `bail`'s body -- asserted under real
// node in
// fixtures/commonjs-circular-import-invocation-provenance-ground-truth/.
const alias = bail;

// ===========================================================================
// THE SAFE-ALIAS CONTROL, and the sharpest one in the file.
//
// The SAME syntax, at module scope, on every load, in a position that is
// unquestionably evaluated -- and it aliases a callable that returns. It
// returns "noop" and module evaluation continues straight past it. An
// analyzer that concluded "an alias invocation is fatal" rather than "THIS
// alias resolves to THIS fatal callable" would cut the module off HERE,
// before either export is written -- right by accident about nothing, and
// wrong about every module in the world that aliases a function.
//
// It is placed ABOVE the branch deliberately: over-firing here is visible
// as a changed verdict, not masked by the real cutoff below.
// ===========================================================================
const safeAlias = noop;
const safeAliasResult = safeAlias();

// A second control on the same axis: an object-literal member whose
// property is OVERWRITTEN before it is called. Reading the literal and
// stopping there resolves `bail`; the language resolves `noop`.
const handlers = { run: bail };
handlers.run = noop;
const handlerResult = handlers.run();

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // ==================================================================
  // THE CUTOFF. This is the entire case.
  //
  // `alias()` enters `bail`, which throws on every path, so module
  // evaluation on this branch ends HERE -- the assignment below is NOT
  // reached on this load, and `module.exports` IS `fastPath`. A cyclic
  // `require()` of this module therefore retains `fastPath` by identity,
  // and calling it reaches vt2-vuln-lib's `dangerousOp`.
  //
  // Before RWF-028 the analyzer had every ingredient of that proof and
  // dropped it because the call site was not a bare identifier: it bound
  // the whole exported value to `slowPath`, gave main()'s call a fully
  // RESOLVED edge to it, left `fastPath` with no incoming edge, and
  // answered NOT_AFFECTED with a COMPLETE Family C proof.
  // ==================================================================
  alias();
}

// Syntactically unconditional, and NOT reached on the fast path.
module.exports = slowPath;

// Deferred decoys: each of these is a shape RWF-028 refuses, and none of
// them runs at module time anyway. They are here so that a rule which
// widened resolution without also keeping its POSITION reasoning would
// have somewhere to go wrong.
function probeIndirect() {
  // Two hops -- past the documented one-hop bound.
  const hop = alias;
  hop();
  // A conditional initializer: which function this names cannot be read
  // off the declaration.
  const conditional = process.env.VT2_CONDITION === "yes" ? bail : noop;
  conditional();
  // A wrapper that catches, and one that keeps a returning path.
  function caught() {
    try {
      bail();
    } catch {
      return "swallowed";
    }
  }
  function returning(flag) {
    if (flag) {
      bail();
    }
    return 1;
  }
  return [caught(), returning(false), safeAliasResult, handlerResult];
}

void probeIndirect;
